def parse_nested_json_with_defaults(json_str, defaults):
    """Parse JSON string and merge with defaults, replacing only null values.

    Args:
        json_str: String containing JSON data
        defaults: Dictionary of default values (may be nested)

    Returns:
        Merged dictionary with nulls replaced by defaults
    """
    data = json.loads(json_str)

    def merge(current, default):
        if current is None:
            return default
        if isinstance(current, dict) and isinstance(default, dict):
            return {
                k: merge(
                    current.get(k),
                    default.get(k) if isinstance(default, dict) else None
                )
                for k in set(current.keys()) | set(default.keys())
            }
        return current

    return merge(data, defaults)", "extension": "py"}

